1const getComputerChoice = () => {
2    const options = ["rock", "paper", "scissors"];
3    let choice = Math.floor(Math.random() * 3);
4    return options[choice];
5};
6
7const getUserChoice = () => {
8    let choice = prompt("Enter your choice: ");
9    choice = choice.toLowerCase();
10    return choice;
11};
12
13const determineOutcome = (computerChoice, userChoice) => {
14    // If both the computer and user choose the same option, it's a draw
15    if (computerChoice === userChoice) {
16        return "Draw";
17    }
18
19    // User wins if they choose paper against rock
20    else if (computerChoice === "rock" && userChoice === "paper") {
21        return "Win";
22    }
23    // User wins if they choose scissors against paper
24    else if (computerChoice === "paper" && userChoice === "scissors") {
25        return "Win";
26    }
27    // User wins if they choose rock against scissors
28    else if (computerChoice === "scissors" && userChoice === "rock") {
29        return "Win";
30    }
31
32    // If none of the above conditions are met, the user loses
33    else {
34        return "Lose";
35    }
36};
37
38// Game Execution
39let computerChoice = getComputerChoice();
40let userChoice = getUserChoice();
41let result = determineOutcome(computerChoice, userChoice);
42
43console.log(`Computer's pick: ${computerChoice}`);
